(6487752, 964960, 117474, '<td valign="top">Never seen quite that before! NICE work!</td>', 'Never seen quite that before! NICE work!', '2011-08-01 22:05:11.000000', NULL, 1),
(6487777, 964668, 42256, '<td valign="top">Interesting portrait - hair and beard tell very different stories! Love the lighting and the catchlight in the eye. Reminds of Louis'' style of processing and tones. I don''t know if the eye patch is distracting or making a statement here!</td>', 'Interesting portrait - hair and beard tell very different stories! Love the lighting and the catchlight in the eye. Reminds of Louis'' style of processing and tones. I don''t know if the eye patch is distracting or making a statement here!', '2011-08-01 22:34:10.000000', NULL, 1),
