(6489764, 963567, 30982, '<td valign="top">Awww.... such a sweet face!</td>', 'Awww.... such a sweet face!', '2011-08-02 23:27:36.000000', NULL, 1),
(6489766, 964882, 30982, '<td valign="top">That looks to be a gorgeous accordian.  I''m not sure about the painting-like background, but it does seem to suit your photograph well.</td>', 'That looks to be a gorgeous accordian.  I''m not sure about the painting-like background, but it does seem to suit your photograph well.', '2011-08-02 23:29:37.000000', NULL, 1),
