(6489857, 964775, 109353, '<td valign="top">Wonderful shot. I understand now why Thoth, the Egyptian god, was ibis-headed man. Impressive bird...</td>', 'Wonderful shot. I understand now why Thoth, the Egyptian god, was ibis-headed man. Impressive bird...', '2011-08-03 00:11:10.000000', NULL, 1),
(6489859, 964361, 112739, '<td valign="top">This is one of the most beautiful shots I have ever seen. The pose is just fantastic. Light and compo couldn''t be better. I wouldn''t be surprised to see this win or very close. Congrats on outstanding work. Thanks.</td>', 'This is one of the most beautiful shots I have ever seen. The pose is just fantastic. Light and compo couldn''t be better. I wouldn''t be surprised to see this win or very close. Congrats on outstanding work. Thanks.', '2011-08-03 00:13:37.000000', NULL, 1),
(6489875, 964632, 30982, '<td valign="top">I like the magical child emerging from the smoking urn-like thing, thorugh the rainbow.  One wonders if herbs of various nature are being burned here.  And all in a surburban back yard.  Quite odd, and intriguing!</td>', 'I like the magical child emerging from the smoking urn-like thing, thorugh the rainbow.  One wonders if herbs of various nature are being burned here.  And all in a surburban back yard.  Quite odd, and intriguing!', '2011-08-03 00:22:41.000000', NULL, 1),
(6489877, 963395, 30982, '<td valign="top">My first thought was "ah, it''s the ballet!" - Lovely!!!</td>', 'My first thought was "ah, it''s the ballet!" - Lovely!!!', '2011-08-03 00:22:59.000000', NULL, 1),
(6489879, 964415, 30982, '<td valign="top">He looks so sad for some reason.</td>', 'He looks so sad for some reason.', '2011-08-03 00:23:17.000000', NULL, 1),
(6489881, 964906, 30982, '<td valign="top">Someone always wants to keep the good things for themselves, when really, sharing is the only way to truly enjoy what you have.  Lovely way to express that in a photograph!</td>', 'Someone always wants to keep the good things for themselves, when really, sharing is the only way to truly enjoy what you have.  Lovely way to express that in a photograph!', '2011-08-03 00:24:08.000000', NULL, 1),
