(6492131, 964613, 65234, '<td valign="top">And one saved for desssert.  At least one.  That''s a very hungry spider, or one who plans ahead ;-)</td>', 'And one saved for desssert.  At least one.  That''s a very hungry spider, or one who plans ahead ;-)', '2011-08-03 23:09:31.000000', NULL, 1),
(6492133, 964075, 65234, '<td valign="top">Now there''s an odd couple!</td>', 'Now there''s an odd couple!', '2011-08-03 23:10:51.000000', NULL, 1),
(6492137, 963770, 76585, '<td valign="top">I love the contrast in the lighting and color. Beautiful! 10</td>', 'I love the contrast in the lighting and color. Beautiful! 10', '2011-08-03 23:14:32.000000', NULL, 1),
(6492139, 964879, 76585, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2011-08-03 23:15:02.000000', NULL, 1),
(6492144, 964931, 65234, '<td valign="top">I have that kind of milkweed and those little butterflies in my garden every summer.  Like the perspective and the light you got on his hairy little body ;-)</td>', 'I have that kind of milkweed and those little butterflies in my garden every summer.  Like the perspective and the light you got on his hairy little body ;-)', '2011-08-03 23:16:48.000000', NULL, 1),
(6492147, 964879, 65234, '<td valign="top">Great detail!</td>', 'Great detail!', '2011-08-03 23:17:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6492154, 964358, 65234, '<td valign="top">For some reason this makes me think of a sad girl who''s father died, but he''s still there in spirit, protecting her like a guardian angel, only she''s too far inside herself to feel his presence.  Quite an evocative image.</td>', 'For some reason this makes me think of a sad girl who''s father died, but he''s still there in spirit, protecting her like a guardian angel, only she''s too far inside herself to feel his presence.  Quite an evocative image.', '2011-08-03 23:21:23.000000', NULL, 1),
(6492162, 963395, 65234, '<td valign="top">Ghostly geese in the night.  This is just so cool!!!</td>', 'Ghostly geese in the night.  This is just so cool!!!', '2011-08-03 23:26:05.000000', NULL, 1),
(6492164, 964891, 65234, '<td valign="top">OMG, look at that tongue!  Incredible.  A little soft in the feathers but I don''t think that matters.  The eyes and beak are sufficiently sharp, and that is what really does justice to a raptor.</td>', 'OMG, look at that tongue!  Incredible.  A little soft in the feathers but I don''t think that matters.  The eyes and beak are sufficiently sharp, and that is what really does justice to a raptor.', '2011-08-03 23:27:57.000000', NULL, 1),
