(6492300, 964332, 68504, '<td valign="top">Bluenesses throughout, managing to encompass all the details with majestic stillness.</td>', 'Bluenesses throughout, managing to encompass all the details with majestic stillness.', '2011-08-04 01:50:24.000000', NULL, 1),
(6492303, 964329, 68504, '<td valign="top">Well, heck, this is a fine composition.  Something about the colours and light everywhere turn this common type of scene into a work of the imagination.</td>', 'Well, heck, this is a fine composition.  Something about the colours and light everywhere turn this common type of scene into a work of the imagination.', '2011-08-04 01:52:14.000000', NULL, 1),
