(6494779, 964201, 19825, '<td valign="top">Very interesting shot. I like the tones on his skin and motion of the water. The white band across the bottom at a slight angle is bit of a distraction.</td>', 'Very interesting shot. I like the tones on his skin and motion of the water. The white band across the bottom at a slight angle is bit of a distraction.', '2011-08-05 21:49:39.000000', NULL, 1),
(6494780, 962130, 19825, '<td valign="top">Love the blue/orange complementary colors. Very nice.</td>', 'Love the blue/orange complementary colors. Very nice.', '2011-08-05 21:52:51.000000', NULL, 1),
(6494782, 963793, 19825, '<td valign="top">Simple, well composed shot. Nice contrast in colors and textures between the grass and water.</td>', 'Simple, well composed shot. Nice contrast in colors and textures between the grass and water.', '2011-08-05 21:55:50.000000', NULL, 1),
(6494784, 962862, 64446, '<td valign="top">I like the miniature effect... as well as the green natural framing. Only observation is that the castle seems a bit tilted to the right.</td>', 'I like the miniature effect... as well as the green natural framing. Only observation is that the castle seems a bit tilted to the right.', '2011-08-05 21:58:08.000000', NULL, 1),
(6494790, 962787, 64446, '<td valign="top">This is very funny, and almost surreal at the same time. Good catch!</td>', 'This is very funny, and almost surreal at the same time. Good catch!', '2011-08-05 22:01:11.000000', NULL, 1),
(6494792, 964407, 19825, '<td valign="top">Nice black and white, I love the detail of the froth the white shirts if the crowd. It is an interesting perspective. It makes me wonder where you were to get this high angle from over the water.</td>', 'Nice black and white, I love the detail of the froth the white shirts if the crowd. It is an interesting perspective. It makes me wonder where you were to get this high angle from over the water.', '2011-08-05 22:03:37.000000', NULL, 1),
(6494793, 964709, 19825, '<td valign="top">This seems like the third shot of these falls so far this Free Study, and I am not that far into it. However, the lighting on this one is unique. Very nice.</td>', 'This seems like the third shot of these falls so far this Free Study, and I am not that far into it. However, the lighting on this one is unique. Very nice.', '2011-08-05 22:06:14.000000', NULL, 1),
(6494794, 964840, 103142, '<td valign="top">Ok. This is really cool...</td>', 'Ok. This is really cool...', '2011-08-05 22:10:50.000000', NULL, 1),
(6494798, 964388, 19825, '<td valign="top">Very cool. Nice shot.</td>', 'Very cool. Nice shot.', '2011-08-05 22:14:39.000000', NULL, 1),
(6494799, 964425, 64446, '<td valign="top">That''s quite unusual a circular rainbow, very well captured with a such a nice view.</td>', 'That''s quite unusual a circular rainbow, very well captured with a such a nice view.', '2011-08-05 22:15:20.000000', NULL, 1),
(6494800, 964328, 69324, '<td valign="top">Nice catch.</td>', 'Nice catch.', '2011-08-05 22:15:54.000000', NULL, 1),
(6494806, 964886, 69324, '<td valign="top">Always hard to get a good dof with two spaced out insects, nice work.</td>', 'Always hard to get a good dof with two spaced out insects, nice work.', '2011-08-05 22:21:42.000000', NULL, 1),
(6494809, 964966, 103142, '<td valign="top">wow. Thought provoking.</td>', 'wow. Thought provoking.', '2011-08-05 22:21:46.000000', NULL, 1),
(6494810, 964621, 103142, '<td valign="top">Nice shot. I like your point of view. And for some reason, I like the eyelashes stuck together.</td>', 'Nice shot. I like your point of view. And for some reason, I like the eyelashes stuck together.', '2011-08-05 22:21:47.000000', NULL, 1),
(6494811, 964935, 103142, '<td valign="top">The sunset is very nice, but foreground is so dark. I wish that you could bring out more of the foreground, or crop up a bit to put the horizon at the 1/3 line. Not that it needs to be, just with all the dark, and not much detail, it gets bottom heavy.</td>', 'The sunset is very nice, but foreground is so dark. I wish that you could bring out more of the foreground, or crop up a bit to put the horizon at the 1/3 line. Not that it needs to be, just with all the dark, and not much detail, it gets bottom heavy.', '2011-08-05 22:21:48.000000', NULL, 1),
(6494812, 964796, 103142, '<td valign="top">Very nice. I''ve never tried a shot like this. Do you have to do something to get the blues, or do they happen naturally?</td>', 'Very nice. I''ve never tried a shot like this. Do you have to do something to get the blues, or do they happen naturally?', '2011-08-05 22:21:49.000000', NULL, 1),
(6494814, 964802, 103142, '<td valign="top">Intriguing shot... I would have liked a little of the bottom cropped, but otherwise I think it''s quite cool.</td>', 'Intriguing shot... I would have liked a little of the bottom cropped, but otherwise I think it''s quite cool.', '2011-08-05 22:22:45.000000', NULL, 1),
(6494815, 964845, 64446, '<td valign="top">Great leading lines and excellent color saturation. I''d try cropping the bottom to eliminate the pipes that distract a bit the whole scene.</td>', 'Great leading lines and excellent color saturation. I''d try cropping the bottom to eliminate the pipes that distract a bit the whole scene.', '2011-08-05 22:23:06.000000', NULL, 1),
(6494820, 964308, 64446, '<td valign="top">Love it!</td>', 'Love it!', '2011-08-05 22:30:14.000000', NULL, 1),
(6494821, 964328, 64446, '<td valign="top">This so cute!</td>', 'This so cute!', '2011-08-05 22:30:49.000000', NULL, 1),
(6494826, 964880, 24486, '<td valign="top">You have captured a lot of energy here. Well done</td>', 'You have captured a lot of energy here. Well done', '2011-08-05 22:34:37.000000', NULL, 1),
(6494827, 964728, 69324, '<td valign="top">Interesting color palette and exposure but what really makes this image is the sense of depth for me, nice work.</td>', 'Interesting color palette and exposure but what really makes this image is the sense of depth for me, nice work.', '2011-08-05 22:36:05.000000', NULL, 1),
(6494828, 960522, 24486, '<td valign="top">Great timing</td>', 'Great timing', '2011-08-05 22:38:13.000000', NULL, 1),
(6494829, 964529, 24486, '<td valign="top">Excellant timing. It is photographs like this that keep encouraging me to photograph rodeos</td>', 'Excellant timing. It is photographs like this that keep encouraging me to photograph rodeos', '2011-08-05 22:40:52.000000', NULL, 1);
