(6495017, 962787, 7889, '<td valign="top">A wonderful moment captured here! My top vote and I hope it gets the blue.</td>', 'A wonderful moment captured here! My top vote and I hope it gets the blue.', '2011-08-06 04:53:21.000000', NULL, 1),
(6495018, 963770, 7889, '<td valign="top">The light falling on the mountains is magical, really like this (apart from that tall tree on the right)and hope it ribbons for you.</td>', 'The light falling on the mountains is magical, really like this (apart from that tall tree on the right)and hope it ribbons for you.', '2011-08-06 04:54:44.000000', NULL, 1),
(6495019, 964361, 7889, '<td valign="top">The detail in this photo is excellent as is the lighting, should be up there in the shake up. Good luck.</td>', 'The detail in this photo is excellent as is the lighting, should be up there in the shake up. Good luck.', '2011-08-06 04:55:34.000000', NULL, 1),
(6495020, 964706, 7889, '<td valign="top">I love b&amp;w and this is just fantastic! Love how the buildings draw my eye to the edge of the ocean. Well done!</td>', 'I love b&w and this is just fantastic! Love how the buildings draw my eye to the edge of the ocean. Well done!', '2011-08-06 04:56:27.000000', NULL, 1),
