(6495022, 964147, 7889, '<td valign="top">Bumping this up because I love the two extremes captured in this photo. You did a great job here.</td>', 'Bumping this up because I love the two extremes captured in this photo. You did a great job here.', '2011-08-06 04:59:33.000000', NULL, 1),
(6495023, 962389, 7889, '<td valign="top">Dreamy quality that really works well, she seems to be at peace with the world.</td>', 'Dreamy quality that really works well, she seems to be at peace with the world.', '2011-08-06 05:00:17.000000', NULL, 1),
(6495024, 962594, 7889, '<td valign="top">Super sharp and the exposure and colours are wonderful, great job with this !</td>', 'Super sharp and the exposure and colours are wonderful, great job with this !', '2011-08-06 05:00:41.000000', NULL, 1),
(6495025, 964267, 7889, '<td valign="top">A kaleidoscope of colours that is just stunning.</td>', 'A kaleidoscope of colours that is just stunning.', '2011-08-06 05:02:01.000000', NULL, 1),
(6495026, 962862, 7889, '<td valign="top">Giving this a second look and bumping it up. I love the darkness of the sky and how it contrasts with the castle.</td>', 'Giving this a second look and bumping it up. I love the darkness of the sky and how it contrasts with the castle.', '2011-08-06 05:02:53.000000', NULL, 1),
(6495028, 963905, 7889, '<td valign="top">A unusual photograph that I suspect will not be too popular with a lot of dpc people but I really think this is an excellent shot. The missing head of the lady really makes this. I think it would work even better in b&amp;w. Good job.</td>', 'A unusual photograph that I suspect will not be too popular with a lot of dpc people but I really think this is an excellent shot. The missing head of the lady really makes this. I think it would work even better in b&w. Good job.', '2011-08-06 05:04:38.000000', NULL, 1),
(6495029, 964959, 7889, '<td valign="top">Just enough blur to make this work, nice and sharp with good colour and exposure.</td>', 'Just enough blur to make this work, nice and sharp with good colour and exposure.', '2011-08-06 05:05:29.000000', NULL, 1),
(6495030, 964673, 7889, '<td valign="top">A simple but effective photograph, the colours are spot on.</td>', 'A simple but effective photograph, the colours are spot on.', '2011-08-06 05:06:14.000000', NULL, 1),
(6495031, 964585, 7889, '<td valign="top">So much going on in this photo! Love the various expressions and it works very well in b&amp;w.</td>', 'So much going on in this photo! Love the various expressions and it works very well in b&w.', '2011-08-06 05:06:58.000000', NULL, 1),
