(6495319, 964859, 11769, '<td valign="top">nice time lapse</td>', 'nice time lapse', '2011-08-06 12:15:29.000000', NULL, 1),
(6495322, 962868, 11769, '<td valign="top">I lost my watch last week, now I know where it went. Good stuff.</td>', 'I lost my watch last week, now I know where it went. Good stuff.', '2011-08-06 12:17:11.000000', NULL, 1),
(6495323, 964795, 11769, '<td valign="top">Beautiful</td>', 'Beautiful', '2011-08-06 12:17:31.000000', NULL, 1),
(6495324, 963896, 59796, '<td valign="top">Phew! Wonderful color gradient. The far clouds are delightfully ablaze. A very nice scene. I would''ve cropped it a little on the right to push the sun to 2/3rds.</td>', 'Phew! Wonderful color gradient. The far clouds are delightfully ablaze. A very nice scene. I would''ve cropped it a little on the right to push the sun to 2/3rds.', '2011-08-06 12:17:33.000000', NULL, 1),
(6495325, 962648, 59796, '<td valign="top">Nice caption! :)<br/>The harsh/clipped shadows lessen the impact of the acrobatics somewhat - would''ve like to see some more definition on the body.</td>', 'Nice caption! :)The harsh/clipped shadows lessen the impact of the acrobatics somewhat - would''ve like to see some more definition on the body.', '2011-08-06 12:20:37.000000', NULL, 1),
(6495327, 964369, 54033, '<td valign="top">:) 10</td>', ':) 10', '2011-08-06 12:21:49.000000', NULL, 1),
(6495328, 961102, 54033, '<td valign="top">What can I say!!! This is so lovely, lighting, composition, tone, story, modeling and processing 10</td>', 'What can I say!!! This is so lovely, lighting, composition, tone, story, modeling and processing 10', '2011-08-06 12:21:52.000000', NULL, 1),
(6495329, 964475, 54033, '<td valign="top">Wow to say the least 10</td>', 'Wow to say the least 10', '2011-08-06 12:21:58.000000', NULL, 1),
(6495330, 964524, 54033, '<td valign="top">I do not usually vote on FS contest but for this photo I will. 10</td>', 'I do not usually vote on FS contest but for this photo I will. 10', '2011-08-06 12:22:04.000000', NULL, 1),
(6495331, 963770, 54033, '<td valign="top">Nice 10</td>', 'Nice 10', '2011-08-06 12:22:07.000000', NULL, 1),
(6495332, 964525, 54033, '<td valign="top">10</td>', '10', '2011-08-06 12:22:14.000000', NULL, 1),
(6495333, 964189, 54033, '<td valign="top">:) 10</td>', ':) 10', '2011-08-06 12:22:17.000000', NULL, 1),
(6495334, 963031, 54033, '<td valign="top">Splendid 9</td>', 'Splendid 9', '2011-08-06 12:22:25.000000', NULL, 1),
(6495335, 964980, 59796, '<td valign="top">I love captures like these - National Geographic style!<br/>However, my OCD immediately kicks in, wanting to straighten the tree. I love the creamy blue background and the nice greens, and although they set the scene, they don''t really add anything to the powerful subject - which is a mom feeding the 2 kids. Could''ve possibly done better with a closer crop I think. Wonderful capture regardless.</td>', 'I love captures like these - National Geographic style!However, my OCD immediately kicks in, wanting to straighten the tree. I love the creamy blue background and the nice greens, and although they set the scene, they don''t really add anything to the powerful subject - which is a mom feeding the 2 kids. Could''ve possibly done better with a closer crop I think. Wonderful capture regardless.', '2011-08-06 12:23:29.000000', NULL, 1),
(6495336, 962681, 11769, '<td valign="top">Beautiful paint job. Those were the days.</td>', 'Beautiful paint job. Those were the days.', '2011-08-06 12:23:54.000000', NULL, 1),
(6495337, 962787, 11769, '<td valign="top">Perfect</td>', 'Perfect', '2011-08-06 12:24:16.000000', NULL, 1),
(6495338, 964358, 11769, '<td valign="top">Profoundly beautiful.</td>', 'Profoundly beautiful.', '2011-08-06 12:25:03.000000', NULL, 1),
(6495339, 964840, 11769, '<td valign="top">Love the curve.</td>', 'Love the curve.', '2011-08-06 12:25:40.000000', NULL, 1),
(6495340, 963697, 59796, '<td valign="top">Sometimes, my OCD prevents me from enjoying what normal people do, I think. Such a wonderful capture with delightful and functional vignetting, and beautiful sepia conversion - spoiled for me by the 3 large sensor dust specks on the sky, smack in the middle :( Still, gets a high score for me, but I hope you clean the sensor soon.</td>', 'Sometimes, my OCD prevents me from enjoying what normal people do, I think. Such a wonderful capture with delightful and functional vignetting, and beautiful sepia conversion - spoiled for me by the 3 large sensor dust specks on the sky, smack in the middle :( Still, gets a high score for me, but I hope you clean the sensor soon.', '2011-08-06 12:25:48.000000', NULL, 1),
(6495341, 964690, 11769, '<td valign="top">Enthralling</td>', 'Enthralling', '2011-08-06 12:26:13.000000', NULL, 1),
(6495342, 964361, 11769, '<td valign="top">Wonderful portrait</td>', 'Wonderful portrait', '2011-08-06 12:26:34.000000', NULL, 1),
(6495343, 964886, 59796, '<td valign="top">Wow! National Geographic time.. <br/>I didn''t see the mantis till I read your title and wondered about it. The delightful creamy background and the sharp dew drops add to the wonderful scene. Very nicely captured!</td>', 'Wow! National Geographic time.. I didn''t see the mantis till I read your title and wondered about it. The delightful creamy background and the sharp dew drops add to the wonderful scene. Very nicely captured!', '2011-08-06 12:27:14.000000', NULL, 1),
(6495345, 964893, 59796, '<td valign="top">Lot''s of layers and textures in the scene. So much detail! It''s delightful. Would''ve loved it even more if you''d shot it standing a little bit left so that the 2 handrails seems balanced.</td>', 'Lot''s of layers and textures in the scene. So much detail! It''s delightful. Would''ve loved it even more if you''d shot it standing a little bit left so that the 2 handrails seems balanced.', '2011-08-06 12:28:26.000000', NULL, 1),
(6495346, 964930, 11769, '<td valign="top">It is great how windows distort their reflections like that.</td>', 'It is great how windows distort their reflections like that.', '2011-08-06 12:28:45.000000', NULL, 1),
(6495347, 964648, 59796, '<td valign="top">Not a fan of the bugs, but this one is captured really nicely. Wonderful soft lighting, creamy bokeh and the diagonal composition - fabulous.</td>', 'Not a fan of the bugs, but this one is captured really nicely. Wonderful soft lighting, creamy bokeh and the diagonal composition - fabulous.', '2011-08-06 12:29:23.000000', NULL, 1),
(6495350, 963360, 59796, '<td valign="top">Black and White! And some grunge style processing... This could''ve been awesome - hair with an attitude!</td>', 'Black and White! And some grunge style processing... This could''ve been awesome - hair with an attitude!', '2011-08-06 12:31:04.000000', NULL, 1),
(6495352, 964850, 59796, '<td valign="top">I think the colors are off a bit - shouldn''t it more purple than blue? Would''ve loved a closeup of the flower - with the bug - would''ve been an awesome fill-the-frame shot. Still, a nice capture.</td>', 'I think the colors are off a bit - shouldn''t it more purple than blue? Would''ve loved a closeup of the flower - with the bug - would''ve been an awesome fill-the-frame shot. Still, a nice capture.', '2011-08-06 12:33:00.000000', NULL, 1),
(6495353, 963702, 86799, '<td valign="top">Made me chuckle out loud.  Cool.</td>', 'Made me chuckle out loud.  Cool.', '2011-08-06 12:33:05.000000', NULL, 1),
(6495354, 964622, 11769, '<td valign="top">Cute as a button</td>', 'Cute as a button', '2011-08-06 12:34:57.000000', NULL, 1),
(6495355, 964983, 86799, '<td valign="top">Very busy background.</td>', 'Very busy background.', '2011-08-06 12:36:14.000000', NULL, 1),
(6495356, 963395, 11769, '<td valign="top">lovely</td>', 'lovely', '2011-08-06 12:36:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6495357, 964839, 11769, '<td valign="top">Wonderful composition.</td>', 'Wonderful composition.', '2011-08-06 12:36:54.000000', NULL, 1),
