(6496748, 964644, 65234, '<td valign="top">Yum; cards are delicious!  As are wrapping paper and boxes, I suspect ;-)  Wonderfully delighted expression.</td>', 'Yum; cards are delicious!  As are wrapping paper and boxes, I suspect ;-)  Wonderfully delighted expression.', '2011-08-07 17:35:00.000000', NULL, 1),
(6496749, 962249, 65234, '<td valign="top">Love the pastels and all the textures.</td>', 'Love the pastels and all the textures.', '2011-08-07 17:35:23.000000', NULL, 1),
(6496751, 962011, 76335, '<td valign="top">I do wish that excellent portraits such as this be left to stand on their own. I don''t feel despair. As such, I now have to step back and consider how well you conveyed what you''re suggesting with your title. <br/> <br/>I see an honest, intimate, piercing portrait -- none of which precludes despair, but I''d rather find it (or not) on my own. <br/> <br/>I say I don''t score titles, but that doesn''t mean I don''t occasionally rant about them. A seven for you.</td>', 'I do wish that excellent portraits such as this be left to stand on their own. I don''t feel despair. As such, I now have to step back and consider how well you conveyed what you''re suggesting with your title.  I see an honest, intimate, piercing portrait -- none of which precludes despair, but I''d rather find it (or not) on my own.  I say I don''t score titles, but that doesn''t mean I don''t occasionally rant about them. A seven for you.', '2011-08-07 17:37:44.000000', NULL, 1),
(6496752, 963552, 65234, '<td valign="top">Very delicate with all the light grasses.  Swallows are tough to capture in flight; I commend you for getting that much detail!!</td>', 'Very delicate with all the light grasses.  Swallows are tough to capture in flight; I commend you for getting that much detail!!', '2011-08-07 17:37:44.000000', NULL, 1),
(6496754, 962875, 76335, '<td valign="top">Beautiful transition of textures here.</td>', 'Beautiful transition of textures here.', '2011-08-07 17:38:14.000000', NULL, 1),
