(6496993, 963484, 73056, '<td valign="top">Beautifully done.</td>', 'Beautifully done.', '2011-08-07 21:52:01.000000', NULL, 1),
(6496995, 962787, 73056, '<td valign="top">Great catch! Nicely done.</td>', 'Great catch! Nicely done.', '2011-08-07 21:53:03.000000', NULL, 1),
(6496996, 964255, 83313, '<td valign="top">Was not sure about where this jumping was going on until I realized that is a pile of ties just like in my recent patterns entry. I like it, though I also wonder what it would look like with a different treatment.</td>', 'Was not sure about where this jumping was going on until I realized that is a pile of ties just like in my recent patterns entry. I like it, though I also wonder what it would look like with a different treatment.', '2011-08-07 21:55:07.000000', NULL, 1),
(6497000, 964468, 83313, '<td valign="top">Grog <b>LOVE</b> rock music! Grog love anything with rocks.</td>', 'Grog LOVE rock music! Grog love anything with rocks.', '2011-08-07 22:00:08.000000', NULL, 1),
(6497001, 963583, 83313, '<td valign="top">The selective desaturation does not look right to me, I''m afraid. Some of it may be the harsh edges on the color to BW edges. When I do selective editing, I usually mask with a soft edged brush and often go back over the edges with a soften brush, to give it a more natural appearance.</td>', 'The selective desaturation does not look right to me, I''m afraid. Some of it may be the harsh edges on the color to BW edges. When I do selective editing, I usually mask with a soft edged brush and often go back over the edges with a soften brush, to give it a more natural appearance.', '2011-08-07 22:03:25.000000', NULL, 1),
(6497002, 964810, 83313, '<td valign="top">A really cute slice of life. The little girl looks so excited! Where do you find pigeons that are this comfortable with people?</td>', 'A really cute slice of life. The little girl looks so excited! Where do you find pigeons that are this comfortable with people?', '2011-08-07 22:05:01.000000', NULL, 1),
(6497006, 964740, 83313, '<td valign="top">I''m very curious about the story that goes along with this shot.</td>', 'I''m very curious about the story that goes along with this shot.', '2011-08-07 22:05:37.000000', NULL, 1),
(6497008, 962253, 83313, '<td valign="top">There is some obvious horizon tilt to this that would have been an easy fix.</td>', 'There is some obvious horizon tilt to this that would have been an easy fix.', '2011-08-07 22:06:41.000000', NULL, 1),
(6497009, 964605, 83313, '<td valign="top">Very cool use of blur. I like the shadowed mysterious figure in the foreground.</td>', 'Very cool use of blur. I like the shadowed mysterious figure in the foreground.', '2011-08-07 22:07:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6497012, 964964, 83313, '<td valign="top">Grog find way to get little lizards to fight and kill each other. Proof of concept good, now Grog work on scaling up to get <strike>tyranesaur</strike> <strike>taran </strike> <strike>terrenas</strike> T-Rex to fight and kill each other. Make safer home for females and younglings.</td>', 'Grog find way to get little lizards to fight and kill each other. Proof of concept good, now Grog work on scaling up to get tyranesaur taran  terrenas T-Rex to fight and kill each other. Make safer home for females and younglings.', '2011-08-07 22:11:37.000000', NULL, 1),
