(6497027, 964767, 83313, '<td valign="top">Looks a lot like <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=19919" rel="nofollow" target="_blank">Kawesttex</a>. Love the Evel Knievel helmet.</td>', 'Looks a lot like  Kawesttex. Love the Evel Knievel helmet.', '2011-08-07 22:21:06.000000', NULL, 1),
